import { readdirSync } from 'node:fs'
import { join } from 'node:path'
import { expect, it } from 'vitest'

/**
 * Every schema change is written three times: `migrations/` (SQLite and D1, generated by drizzle),
 * `migrations-postgres/` and `migrations-mariadb/`. Each runner applies files in name order and
 * records each name as a primary key, so files are never renamed; their numbers already differ.
 * This test makes the correspondence visible instead of remembered.
 */

const root = join(import.meta.dirname, '..')

/** The first SQLite migration written for all three dialects; earlier ones predate the ports. */
const FIRST_SHARED = '0026_reservation_expiry_index.sql'

/** Drizzle names some SQLite migrations itself; their counterparts carry the descriptive name. */
const SQLITE_NAMES: Readonly<Record<string, string>> = {
  overconfident_micromacro: 'archive_lease',
}

/** Migrations one dialect needs and the others do not. */
const DIALECT_ONLY: Readonly<Record<'postgres' | 'mariadb', readonly string[]>> = {
  postgres: [],
  // Missing-row locks vanish at READ COMMITTED, so MariaDB fences region deletion with a lock row.
  mariadb: ['region_deletion_fence'],
}

const migrations = (directory: string): string[] =>
  readdirSync(join(root, directory))
    .filter((name) => name.endsWith('.sql'))
    .sort()

/** The migration's subject: its name without the number, extension, or separator style. */
const subject = (file: string): string => {
  const name = file
    .replace(/^\d+_/, '')
    .replace(/\.sql$/, '')
    .replaceAll('-', '_')
  return SQLITE_NAMES[name] ?? name
}

const shared = migrations('migrations')
  .filter((file) => file >= FIRST_SHARED)
  .map(subject)

it.each(['postgres', 'mariadb'] as const)(
  'gives every shared SQLite migration a %s counterpart, in the same order',
  (dialect) => {
    const subjects = migrations(`migrations-${dialect}`).map(subject)
    const first = subjects.indexOf(subject(FIRST_SHARED))
    expect(first).toBeGreaterThan(0)
    const counterparts = subjects
      .slice(first)
      .filter((name) => !DIALECT_ONLY[dialect].includes(name))
    expect(counterparts).toEqual(shared)
  },
)
